    private void btnSimpanActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnSimpanActionPerformed
        // TODO backend: wajib pilih tugas di tblPilihTugas dan status progres; simpan progres lewat ProgresPenangananDAO
        if (tglSelesai.isSelected()) {
            konfirmasi("Progres dicatat, penugasan selesai", "Laporan L-0104 kini berstatus Selesai dan kondisi Lift L-02 diperbarui menjadi Baik.",
                    "OK", new java.awt.Color(21, 128, 61), new java.awt.Color(234, 88, 12), false);
        } else {
            konfirmasi("Progres dicatat", "Progres penanganan berhasil disimpan.",
                    "OK", new java.awt.Color(21, 128, 61), new java.awt.Color(234, 88, 12), false);
        }
        tampil("tugas");
    }//GEN-LAST:event_btnSimpanActionPerformed

    private void tblTugasMouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_tblTugasMouseClicked
        if (klikAksi(tblTugas, evt)) {
            tampil("perbarui");
        }
    }//GEN-LAST:event_tblTugasMouseClicked


    private void tampil(String kartu) {
        ((java.awt.CardLayout) getLayout()).show(this, kartu);
    }

    /** Menampilkan salah satu halaman di view ini (nama kartu: lihat Navigator). */
    public void tampilkan(String kartu) {
        tampil(kartu);
    }

    /** true jika klik berada pada kolom terakhir (Aksi) sebuah baris tabel. */
    private static boolean klikAksi(javax.swing.JTable t, java.awt.event.MouseEvent evt) {
        return t.rowAtPoint(evt.getPoint()) >= 0 && t.columnAtPoint(evt.getPoint()) == t.getColumnCount() - 1;
    }

    /** true jika klik berada di sisi kiri sel Aksi (tautan pertama, mis. "Ubah"). */
    private static boolean klikTautanPertama(javax.swing.JTable t, java.awt.event.MouseEvent evt) {
        java.awt.Rectangle r = t.getCellRect(t.rowAtPoint(evt.getPoint()), t.getColumnCount() - 1, false);
        return evt.getX() - r.x < 52;
    }

    private boolean konfirmasi(String judul, String pesan, String aksi, java.awt.Color warnaJudul, java.awt.Color warnaAksi, boolean adaBatal) {
        java.awt.Window w = javax.swing.SwingUtilities.getWindowAncestor(this);
        DialogKonfirmasi dlg = new DialogKonfirmasi(w instanceof java.awt.Frame ? (java.awt.Frame) w : null, true);
        dlg.setKonten(judul, pesan, aksi, warnaJudul, warnaAksi, adaBatal);
        dlg.setLocationRelativeTo(this);
        dlg.setVisible(true);
        return dlg.isKonfirmasi();
    }

